window.IPAS_QUESTIONS = [
  {id:"1151j1-1",examId:"115-1-j1",n:1,topic:"資料整合",prompt:"下列何者不屬於資料整合（Data Integration）的主要目的？",options:["統一不同來源資料的格式與欄位定義，以確保分析一致性","識別並處理重複資料，避免影響模型訓練結果","整併多來源資料，以提升資料完整性與應用價值","依資料保存政策延長原始資料留存期限，以利未來可能的分析需求"],answer:3,explanation:"資料整合著重於統一格式、處理重複資料並整併來源，讓資料能一致地分析與使用。延長資料留存期限屬於資料治理與保存政策，並非資料整合的主要目的。",distractors:["混淆格式整合與資料治理","把清理重複資料誤認為無關步驟","把多來源整併誤認為無關步驟"]},
  {id:"1151j1-2",examId:"115-1-j1",n:2,topic:"感測網路",prompt:"某智慧城市專案導入 AI 技術，以優化垃圾收集路線調度並即時監測空氣品質變化。系統需持續蒐集環境數據（如 PM2.5、氣體濃度）與設備狀態（如垃圾桶滿溢度）。下列何種技術最直接支援上述需求？",options:["專家系統（Expert System）","決策支援系統（Decision Support System）","啟發式決策引擎（Heuristic Decision Engine）","感知器網路（Sensor Network）"],answer:3,explanation:"題目關鍵是持續從環境與設備蒐集即時狀態資料。感測器網路負責連接感測裝置並傳送觀測值；專家系統和決策支援系統主要用於規則推論或輔助決策。",distractors:["把規則推論系統當成資料蒐集設備","把決策工具當成感測來源","把決策策略方法當成感測網路"]},
  {id:"1151j1-3",examId:"115-1-j1",n:3,topic:"非監督式學習",prompt:"下列何者不符合非監督式學習（Unsupervised Learning）的典型特徵？",options:["模型可依據資料中的特徵相似性進行自動分群","訓練過程中不需仰賴事先定義的標籤資料","常用於探索資料的潛在結構或隱含模式","模型主要學習輸入特徵與既定目標標記之間的對應關係"],answer:3,explanation:"非監督式學習使用未標記資料探索結構，例如分群。從輸入特徵學習預先標註的目標值，描述的是監督式學習。",distractors:["把分群誤認為需要標籤","忽略非監督式學習的無標籤特性","把監督式學習特徵歸給非監督式學習"]},
  {id:"1151j1-4",examId:"115-1-j1",n:4,topic:"離群值",prompt:"某保險公司建立 AI 理賠金額預測模型。歷史理賠資料經檢定後呈近似常態分佈，但仍存在少數極端高額案件。資料科學團隊在不破壞整體分佈特性的前提下，規劃進行離群值處理。下列何者最不適當？",options:["依統計準則（如 Z-score 或 IQR）評估後，再決定是否調整或處理極端值","採用截尾（Trimming）處理極端值，以提升模型穩定性","使用 One-hot 編碼（One-hot Encoding）將離群值轉換為類別特徵以改善數值穩定性","結合領域知識評估其合理性，再決定保留或修正"],answer:2,explanation:"One-hot 編碼用來表示類別特徵，不是連續數值離群值的通用處理方式。離群值應先確認是錯誤資料還是真實高額案件，再依統計準則和領域知識決定保留、轉換或處理。",distractors:["把統計檢測誤當成一定破壞分布","截尾可能造成資訊損失，但屬可評估的處理方法","把領域判斷誤認為不適用"]},
  {id:"1151j1-5",examId:"115-1-j1",n:5,topic:"類別不平衡",prompt:"某銀行建立 AI 詐欺交易偵測模型。歷史交易資料中，詐欺樣本比例極低，導致模型訓練時偏向預測為「正常交易」。資料科學團隊評估採用 SMOTE 改善訓練資料分佈。下列何者最符合 SMOTE 技術的主要功能？",options:["透過隨機刪除部分正常交易資料，以降低類別失衡程度","依據少數類別樣本的特徵空間，合成產生新的少數類別樣本","調整模型的損失函數權重，使誤判少數類別時的懲罰提高","以交叉驗證方式重新分割資料集，使各折資料類別比例一致"],answer:1,topicTags:["資料前處理","分類"],explanation:"SMOTE 在少數類別樣本之間插值，合成新的少數類別訓練樣本，以緩解類別不平衡。調整損失權重是另一類方法，交叉驗證則用於評估模型。",distractors:["較接近欠抽樣（undersampling）","正確：以少數類別鄰近樣本合成新資料","描述的是類別加權損失","描述的是分層交叉驗證"]},
  {id:"1151j1-6",examId:"115-1-j1",n:6,topic:"資料洩漏",prompt:"資料科學團隊在模型訓練前，需對數值特徵進行正規化或標準化。為確保模型評估結果具真實性並避免資料洩漏，下列何者為最適當的作法？",options:["於資料分割前，先對完整資料集計算統計量並進行標準化處理","先分割訓練資料和測試資料，並各自獨立計算統計量後進行標準化","先分割訓練資料和測試資料，僅以訓練資料計算統計量，再套用至測試資料","僅對訓練資料進行標準化處理，測試資料保持原始數值"],answer:2,explanation:"測試集必須模擬未見資料。先切分資料，再只用訓練集估計平均值、標準差或縮放範圍，並把同一轉換套用到測試集，才能避免測試資訊洩漏到前處理流程。",distractors:["完整資料含測試集資訊，會造成洩漏","訓練與測試各自估計轉換量，評估流程不一致","訓練和測試資料尺度不一致"]},
  {id:"1151j1-7",examId:"115-1-j1",n:7,topic:"類別特徵編碼",prompt:"某電信公司建立機器學習模型預測用戶流失風險。資料中包含「資費方案類型」與「客戶地區」等類別型特徵。為使模型能有效使用這些特徵，下列哪種處理方式最直接？",options:["One-hot 編碼","對類別名稱做字母排序後直接當作連續數值","刪除所有類別型特徵","以每個類別的文字長度作為特徵值"],answer:0,explanation:"One-hot 編碼為每個類別建立 0/1 欄位，避免把沒有大小順序的類別錯誤解讀為連續數值。實務上仍需考慮類別數量與模型對特徵表示的需求。",distractors:["字母順序會引入不存在的大小關係","直接刪除會失去可能有用的預測資訊","字串長度通常沒有合理的類別語意"]},
  {id:"1151j2-1",examId:"115-1-j2",n:1,topic:"模型偏差",prompt:"某零售企業導入生成式 AI 商品推薦系統。測試顯示，在購物行為、偏好設定與價格區間相同的情況下，不同客戶族群收到的推薦商品類型仍出現明顯差異。若要優先降低可能的模型偏差風險，下列何者最合理？",options:["重新檢視訓練資料的樣本分布與代表性","限制推薦結果僅顯示高銷量商品","降低模型參數規模以簡化決策邏輯","提高推薦結果的隨機性以增加多樣性"],answer:0,explanation:"當相似條件的不同族群收到系統性不同結果時，應先檢查資料是否能代表各族群，以及標籤和歷史決策是否帶有偏差。改變商品熱度、模型大小或隨機性都不能直接確認偏差來源。",distractors:["熱銷限制可能掩蓋差異，無法診斷偏差","模型縮小不保證公平性","增加隨機性可能改變結果，卻不處理系統性偏差"]},
  {id:"1151j2-2",examId:"115-1-j2",n:2,topic:"參數高效微調",prompt:"企業進行大型語言模型的 Fine-tuning 時，GPU 運算資源與記憶體嚴重受限。若希望維持模型效能並顯著降低需更新的參數數量，哪種參數高效微調技術最合適？",options:["知識蒸餾（Knowledge Distillation）","提示詞工程（Prompt Engineering）","梯度凍結（Gradient Freezing）","低秩適配（LoRA）"],answer:3,explanation:"LoRA 凍結預訓練權重，在模型層中加入低秩可訓練矩陣，只更新少量參數，因此能減少微調的記憶體和計算需求。",distractors:["蒸餾把知識轉移到較小模型，並非此處的微調方式","提示詞工程不更新模型參數","凍結權重本身未指定有效的可訓練適配參數"]},
  {id:"1151j2-3",examId:"115-1-j2",n:3,topic:"低程式碼平台",prompt:"某企業規劃透過 Low-Code 平台建置可視化儀表板，以支援營運數據的即時監控與分析判讀。若企業特別關注儀表板顯示結果的穩定性與分析可信度，最應優先確認什麼？",options:["是否具備穩定的資料串接能力與即時更新機制","是否提供自動化決策建議與預測分析模組","是否支援彈性介面設計與多角色權限管理","是否提供豐富的主題樣式與配色選擇"],answer:0,explanation:"儀表板可信度首先取決於輸入資料是否穩定、正確且能依需求更新。介面功能和外觀有助於使用，但無法彌補資料串接品質不佳。",distractors:["自動建議不是資料正確性的來源","權限很重要，但不直接確保數據即時且正確","視覺樣式不決定資料可信度"]},
  {id:"1152j1-1",examId:"115-2-j1",n:1,topic:"情感分析",prompt:"地方政府分析選舉期間的社群媒體貼文，希望了解選民對政策議題的態度，並避免辨識特定個人。哪種技術組合最符合需求？",options:["情感分析結合關鍵詞提取，分析貼文立場與高頻議題詞彙","文本分類結合人臉辨識，辨識發文者後再分類政治立場","語音辨識結合影像辨識，把造勢影片轉成文字後整理主題","推薦系統結合社群圖譜，預測個別使用者的投票選擇"],answer:0,explanation:"研究對象是貼文內容中的態度和議題詞彙，因此情感分析與關鍵詞提取直接對應目標，也不需要識別發文者。",distractors:["加入身分辨識超出需求並涉及個人辨識","可處理影片內容，但不是分析文字貼文的直接方案","個人投票預測偏離政策態度分析目標"]},
  {id:"1152j1-2",examId:"115-2-j1",n:2,topic:"機器學習方式",prompt:"物流公司評估異常包裹偵測、路線規劃與倉儲動線分析。下列對機器學習方式的敘述何者有誤？",options:["監督式學習可用於異常包裹偵測，前提是有已標註正常或異常的歷史資料","非監督式學習可探索倉儲動線的潛在分群，但不直接提供特定行為正誤標記","強化學習可透過環境回饋逐步找出配送策略","非監督式學習在沒有標註資料時，也能準確判定每筆資料屬於特定異常類別"],answer:3,explanation:"非監督式方法能找出偏離群集的樣本或探索結構，但沒有標籤時通常不能直接保證每筆樣本屬於哪個已定義異常類別。題目要求的確定分類通常需要標註、規則或後續驗證。",distractors:["已標註資料符合監督式學習","描述符合非監督式探索用途","描述符合強化學習的回饋機制"]},
  {id:"1152j2-1",examId:"115-2-j2",n:1,topic:"檢索增強生成",prompt:"會計師事務所用 Low-Code 工具處理多種格式的費用單據，各企業的科目規則不同。比較直接呼叫基礎語言模型 API，與使用內建 RAG 元件比對過去已正確分類的單據，下列分析何者較正確？",options:["基礎模型具通用知識，足以應對所有格式與規則","RAG 可提供歷史分類案例作為參考上下文，協助提升分類準確率","兩種方式效果相同，差異只有系統複雜度","固定分類規則一定能處理各種單據，無需模型或案例"],answer:1,explanation:"RAG 在回答前檢索相關案例或規範，並將內容提供給模型作為上下文。對企業特有的分類規則，這能讓模型參照可追溯資料；實際成效仍需以該企業資料測試。",distractors:["通用知識不能保證符合特定企業規則","正確：檢索案例提供任務相關依據","兩種架構的可用資訊與回應方式不同","格式多樣且規則不同，固定規則未必足夠"]},
  {id:"1152j2-2",examId:"115-2-j2",n:2,topic:"流程控制",prompt:"Low-Code 自動化流程設定為：當客戶訊息被 AI 判定為「退費意圖」，且退費金額大於 10,000 元時，發送緊急通知給主管。最可能使用哪種元件？",options:["條件分支（Branching / Router）","資料格式化（Formatter）","迭代／迴圈（Iterator）","陣列聚合器（Array Aggregator）"],answer:0,explanation:"流程要根據意圖和金額條件選擇不同路徑，因此使用條件分支或路由元件。格式化處理資料格式，迴圈逐筆處理集合，聚合器則整理多筆資料。",distractors:["格式化不負責條件路徑判斷","迭代用於逐項處理資料集合","聚合器用於彙整集合資料"]},
  {id:"1153j1-1",examId:"115-3-j1",n:1,topic:"監督式學習",prompt:"製造工廠整理過去五年的設備資料，工程師已將每筆資料標示為「正常運作」或「發生故障」。若要用這批資料訓練分類模型，最適合哪種機器學習方法？",options:["監督式學習","非監督式學習","強化學習","半監督式學習"],answer:0,explanation:"資料已有明確的故障／正常標籤，模型可以從特徵與標籤的對應關係學習分類規則，這是監督式學習。",distractors:["非監督式學習處理無標籤資料","強化學習透過行動和回饋學習策略","半監督式學習通常同時使用少量標記和大量未標記資料"]},
  {id:"1153j1-2",examId:"115-3-j1",n:2,topic:"監督與非監督",prompt:"電商平台有一部分會員交易資料已標註「是否流失」，另一部分只有瀏覽、購買及搜尋紀錄，沒有結果標籤。下列哪種描述最適當？",options:["已標註流失結果的資料適合監督式學習；未標註行為資料可用非監督式學習探索族群特徵","已標註流失結果適合非監督式學習；未標註行為資料需先人工分類才能進行監督式學習","兩類資料都只能用監督式學習","兩類資料都屬生成式 AI 訓練資料，無法用於機器學習"],answer:0,explanation:"是否流失是可供模型學習的標籤，適合監督式預測；未標記行為可用分群等非監督方法探索會員型態。",distractors:["顛倒了有標籤和無標籤資料的用途","忽略無標籤資料可用於探索性分析","一般機器學習可使用此類交易資料"]},
  {id:"1153j2-1",examId:"115-3-j2",n:1,topic:"多雲部署",prompt:"跨國零售企業將部分服務和資料部署在不同雲端平台，並評估使用 No-Code／Low-Code 平台建置應用。導入前最應確認什麼？",options:["Multi-Cloud 只影響基礎設施，因此不影響平台部署能力","只要支援跨雲資料連線，就無需評估應用程式部署限制","應確認平台支援規劃中的多雲部署需求，並符合資安及法規要求","多雲環境必須一律改用傳統程式開發"],answer:2,explanation:"不同低程式碼平台的部署、資料連線和治理能力不同。應以企業預定的雲端配置、資安控管與法規條件逐項確認，不宜只看開發效率或單一連線功能。",distractors:["部署和治理能力可能受雲端配置影響","資料連線不能替代部署及法遵評估","是否改用傳統開發需依實際需求評估"]},
  {id:"1153j2-2",examId:"115-3-j2",n:2,topic:"低程式碼平台",prompt:"製造工廠希望將紙本巡檢表單數位化，建立巡檢紀錄、異常通報與簽核流程，但資訊部門人力有限。評估導入 Low-Code 平台的主要優勢為何？",options:["平台自動把所有紙本轉成完整系統，完全不需維護","現成元件和連接器可縮短部分應用建置時間，仍需評估整合與維護","平台可直接串接所有舊機台，無需任何設定","非專業人員建立的應用會自動符合所有資安法規"],answer:1,explanation:"Low-Code 提供視覺化建置工具和可重用元件，能減少部分程式撰寫並加快交付。整合舊系統、資安檢查和後續維護仍須規劃，不能假定完全自動完成。",distractors:["平台不能保證無需人工整理或維護","正確：重用元件有助縮短建置，但非零成本","整合舊設備仍需檢查介面與資料格式","資安法遵仍需治理與稽核"]}
];
